SELECT

FROM code_session_outbound_events
WHERE workspace_uuid = #{workspaceUUID}
  AND idempotency_key = #{idempotencyKey}
  AND deleted_at IS NULL
LIMIT 1

SELECT

FROM code_session_outbound_events
WHERE code_session_external_id = #{codeSessionExternalID}
  AND sequence_num > #{afterSequence}
  AND deleted_at IS NULL
ORDER BY sequence_num ASC
LIMIT #{limit}
